INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3306-4000-8000-000000000006', 'b1b2c3d4-3333-4000-8000-000000000003', 6, 'Quiz: Discernimento', 'Teste seus conhecimentos', '{"questions": [{"q": "Segundo Santo In\u00e1cio, o que N\u00c3O se deve fazer em tempo de desola\u00e7\u00e3o?", "correct": 1, "options": ["Rezar mais", "Fazer mudan\u00e7as importantes", "Buscar dire\u00e7\u00e3o espiritual", "Jejuar"]}, {"q": "Qual \u00e9 o primeiro passo do discernimento vocacional?", "correct": 1, "options": ["Pesquisar semin\u00e1rios", "Dispor-se a ouvir a vontade de Deus", "Consultar amigos", "Fazer um retiro"]}, {"q": "Quantas voca\u00e7\u00f5es fundamentais a Igreja reconhece?", "correct": 2, "options": ["2", "3", "4", "5"]}]}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;